"""Test list for the MHPCO Claim Office kata.

Observable contract for rejections: the specification says the CLI "exits with
a non-zero status code and writes an error description to stderr". The reading
adopted here is that the domain layer raises a `ValueError` carrying a
description, and the CLI adapter translates that into exit status 1 plus a
stderr message. Tests below state which of the two observations they make.
"""

import pytest

# --- Premium: fee and single items -----------------------------------------


@pytest.mark.skip(reason="TODO: empty item list -> premium 5 G (processing fee only)")
def test_empty_item_list_costs_only_the_processing_fee():
    """Quote with no items yields premium 5 G."""


@pytest.mark.skip(reason="TODO: plain sword -> 100 G base + 10 G first insurance + 5 G fee = 115 G")
def test_plain_sword_premium():
    """Quote for a plain sword for a newcomer yields premium 115 G."""


@pytest.mark.skip(reason="TODO: plain amulet -> 60 G base + 6 G first insurance + 5 G fee = 71 G")
def test_plain_amulet_premium():
    """Quote for a plain amulet for a newcomer yields premium 71 G."""


@pytest.mark.skip(reason="TODO: plain staff -> 80 G base + 8 G first insurance + 5 G fee = 93 G")
def test_plain_staff_premium():
    """Quote for a plain staff for a newcomer yields premium 93 G."""


@pytest.mark.skip(reason="TODO: plain potion -> 40 G base + 4 G first insurance + 5 G fee = 49 G")
def test_plain_potion_premium():
    """Quote for a plain potion for a newcomer yields premium 49 G."""


@pytest.mark.skip(reason="TODO: single rune -> 25 G base + 2.5 G first insurance + 5 G fee = 33 G (rounded up)")
def test_single_rune_premium():
    """Quote for one rune yields premium 33 G (32.5 rounded up in MHPCO's favor)."""


@pytest.mark.skip(reason="TODO: single moonstone -> 25 G base, same component price list entry as rune")
def test_single_moonstone_premium():
    """Quote for one moonstone yields the same premium as one rune: 33 G."""


# --- Component building blocks ---------------------------------------------


@pytest.mark.skip(reason="TODO: 2 runes -> 50 G base premium (no block)")
def test_two_runes_base_premium_is_50():
    """Two runes give a policy base premium of 50 G."""


@pytest.mark.skip(reason="TODO: 3 runes -> 60 G base premium (block applies)")
def test_three_runes_form_a_block_worth_60():
    """Three alike runes give a policy base premium of 60 G."""


@pytest.mark.skip(reason="TODO: 4 runes -> 100 G base premium (block requires exactly 3)")
def test_four_runes_get_no_block():
    """Four runes give a policy base premium of 100 G, not 60 + 25."""


@pytest.mark.skip(reason="TODO: 7 runes -> 175 G base premium")
def test_seven_runes_base_premium_is_175():
    """Seven runes give a policy base premium of 175 G."""


@pytest.mark.skip(reason="TODO: 2 runes + 1 moonstone -> 75 G (alike means same type, no block)")
def test_mixed_component_types_do_not_form_a_block():
    """Two runes plus one moonstone give 75 G: 'alike' means same type."""


@pytest.mark.skip(reason="TODO: 3 runes + 3 moonstones -> 120 G (two separate blocks)")
def test_two_separate_blocks_of_different_component_types():
    """Three runes plus three moonstones give 120 G as two separate blocks."""


# --- Item-specific modifiers ------------------------------------------------


@pytest.mark.skip(reason="TODO: cursed sword adds 50 % of its own base premium (50 G)")
def test_cursed_item_adds_fifty_percent_surcharge():
    """A cursed sword's curse surcharge is 50 G."""


@pytest.mark.skip(reason="TODO: enchantment 5 adds 30 % of the item base premium (30 G on a sword)")
def test_enchantment_five_adds_high_enchantment_surcharge():
    """A sword with exactly enchantment 5 carries the 30 % surcharge."""


@pytest.mark.skip(reason="TODO: enchantment 4 adds no high-enchantment surcharge")
def test_enchantment_four_adds_no_high_enchantment_surcharge():
    """A sword with enchantment 4 carries no high-enchantment surcharge."""


@pytest.mark.skip(reason="TODO: cursed sword with enchantment 5 -> both surcharges apply")
def test_cursed_and_highly_enchanted_item_gets_both_surcharges():
    """A cursed sword with enchantment 5 gets 50 G curse plus 30 G enchantment."""


@pytest.mark.skip(reason="TODO: item modifier uses only the affected item's base premium, not the policy total")
def test_curse_surcharge_scopes_to_the_cursed_item_only():
    """Cursed sword + plain amulet: base 160 G, curse adds 50 G -> 210 G before fee/first insurance."""


# --- Policy-wide modifiers --------------------------------------------------


@pytest.mark.skip(reason="TODO: 2 years with MHPCO -> 20 % loyalty discount on the policy base premium")
def test_exactly_two_years_grants_the_loyalty_discount():
    """A customer with exactly 2 years receives the 20 % loyalty discount."""


@pytest.mark.skip(reason="TODO: 1 year with MHPCO -> no loyalty discount")
def test_one_year_grants_no_loyalty_discount():
    """A customer with 1 year receives no loyalty discount."""


@pytest.mark.skip(reason="TODO: first insurance surcharge is 10 % of the policy base premium")
def test_first_insurance_surcharge_applies_to_every_quote():
    """Every quoted item is treated as a first insurance: +10 % of policy base premium."""


@pytest.mark.skip(reason="TODO: second quote in a scenario gets a 15 % follow-up contract discount")
def test_second_contract_receives_the_follow_up_discount():
    """The customer's second quote receives a 15 % discount on the policy base premium."""


@pytest.mark.skip(reason="TODO: third quote also receives the follow-up discount (each contract after the first)")
def test_third_contract_also_receives_the_follow_up_discount():
    """Every contract after the first receives the 15 % follow-up discount."""


@pytest.mark.skip(reason="TODO: processing fee 5 G is added at the very end, after all modifiers")
def test_processing_fee_is_added_last():
    """The 5 G processing fee is added after all percentage modifiers."""


# --- Rounding ----------------------------------------------------------------


@pytest.mark.skip(reason="TODO: premium 197.5 G -> 198 G (rounded up, in MHPCO's favor)")
def test_premium_is_rounded_up():
    """A premium computation yielding 197.5 G becomes 198 G."""


@pytest.mark.skip(reason="TODO: intermediate amounts stay fractional; only the final premium is rounded")
def test_only_the_final_premium_is_rounded():
    """Fractional intermediate amounts are not rounded before the final premium."""


# --- Integration examples ----------------------------------------------------


@pytest.mark.skip(reason="TODO: newcomer with a cursed sword -> premium 165 G")
def test_newcomer_with_a_cursed_sword_pays_165():
    """0 years, cursed steel sword enchantment 3: 100 + 50 + 10 + 5 = 165 G."""


@pytest.mark.skip(reason="TODO: long-standing customer's second contract -> premium 160 G")
def test_long_standing_customers_second_contract_pays_160():
    """3 years, second quote, cursed sword enchantment 7: 100+50+30-20+10-15+5 = 160 G."""


# --- Insurance sum and cap ---------------------------------------------------


@pytest.mark.skip(reason="TODO: sword + amulet -> insurance sum 1600 G, cap 3200 G")
def test_cap_is_twice_the_insurance_sum_of_all_items():
    """A policy over a sword and an amulet has a cap of 3200 G."""


@pytest.mark.skip(reason="TODO: two swords -> insurance sum 2000 G, cap 4000 G")
def test_two_items_of_the_same_type_both_count_towards_the_insurance_sum():
    """A policy over two swords has an insurance sum of 2000 G and a cap of 4000 G."""


@pytest.mark.skip(reason="TODO: cursed sword -> cap 2000 G; premium modifiers do not raise the cap")
def test_premium_modifiers_do_not_raise_the_cap():
    """A cursed sword's cap stays 2000 G, based on the unmodified insurance value."""


@pytest.mark.skip(reason="TODO: sword + 3 runes -> insurance sum 1750 G; block discount does not lower the sum")
def test_block_discount_does_not_lower_the_insurance_sum():
    """A sword plus a block of 3 runes has an insurance sum of 1750 G."""


# --- Claim payout ------------------------------------------------------------


@pytest.mark.skip(reason="TODO: steel sword enchantment 3, damage 500 -> payout 400 G (deductible only)")
def test_standard_reimbursement_subtracts_the_deductible():
    """A regular sword damaged for 500 G pays out 400 G."""


@pytest.mark.skip(reason="TODO: rune damage 200 -> payout 100 G (no enchantment or material clause)")
def test_component_without_enchantment_or_material_gets_standard_reimbursement():
    """A rune damaged for 200 G pays out 100 G."""


@pytest.mark.skip(reason="TODO: steel sword enchantment 9, damage 1000 -> payout 400 G (50 % then deductible)")
def test_high_enchantment_halves_the_damage_before_the_deductible():
    """An enchantment-9 steel sword damaged for 1000 G pays out 400 G."""


@pytest.mark.skip(reason="TODO: enchantment exactly 8 is the threshold for the 50 % clause")
def test_enchantment_eight_triggers_the_half_reimbursement_clause():
    """A dragon-material sword with exactly enchantment 8, damage 1000 G, pays out 400 G."""


@pytest.mark.skip(reason="TODO: enchantment 7 does not trigger the 50 % clause")
def test_enchantment_seven_does_not_trigger_the_half_reimbursement_clause():
    """A steel sword with enchantment 7 damaged for 1000 G pays out 900 G."""


@pytest.mark.skip(reason="TODO: dragon material, enchantment 5, damage 800 -> payout 700 G (full then deductible)")
def test_dragon_material_alone_is_fully_reimbursed():
    """A dragon-material sword with enchantment 5 damaged for 800 G pays out 700 G."""


@pytest.mark.skip(reason="TODO: dragon material + enchantment 9, damage 1000 -> payout 400 G (50 % rule wins)")
def test_high_enchantment_wins_over_dragon_material():
    """A dragon-material sword with enchantment 9 damaged for 1000 G pays out 400 G."""


@pytest.mark.skip(reason="TODO: deductible applies once per damaged item: 500 + 300 -> payout 600 G")
def test_deductible_applies_once_per_damage_entry():
    """Two damaged items (500 G and 300 G) pay out 600 G in total."""


@pytest.mark.skip(reason="TODO: two entries of the same item type are two separate damages with their own deductibles")
def test_two_damages_of_the_same_item_type_each_carry_a_deductible():
