@pytest.mark.skip(reason="TODO: damage below the deductible does not produce a negative payout")
def test_damage_below_the_deductible_pays_out_nothing():
    """A damage of 50 G with a 100 G deductible pays out 0 G, not -50 G."""


# --- Cap exhaustion across claims -------------------------------------------


@pytest.mark.skip(reason="TODO: first claim of 1500 G on a 1000 G sword -> payout 1400 G, remainingCap 600 G")
def test_first_claim_reports_the_remaining_cap():
    """A 1500 G claim on a sword pays 1400 G and leaves 600 G of cap."""


@pytest.mark.skip(reason="TODO: second claim of 1500 G -> payout 600 G, remainingCap 0 G")
